package com.gerenciadorrural.modules.herd.application; import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.shared.tenancy.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class GetCurrentFarmAnimalHistory {private final TenantTransactionExecutor tx;private final HerdAnimalProfileRepository animals;private final AnimalEventRepository events;public GetCurrentFarmAnimalHistory(TenantTransactionExecutor tx,HerdAnimalProfileRepository animals,AnimalEventRepository events){this.tx=tx;this.animals=animals;this.events=events;}public Result execute(TenantContext c,UUID id,AnimalEventType type,int page,int size){return tx.execute(c,()->{animals.findById(c.tenantId(),c.farmId(),id).orElseThrow(HerdAnimalNotFoundException::new);long total=events.count(c.tenantId(),c.farmId(),id,type);return new Result(events.history(c.tenantId(),c.farmId(),id,type,size,(long)page*size),page,size,total);});} public record Result(List<AnimalEvent> items,int page,int size,long totalElements){public int totalPages(){return totalElements==0?0:(int)((totalElements+size-1)/size);}}}
